    std::string error;      // set when the run aborted (bad op, step budget)
    long long steps = 0;
    std::vector<int> kicks;         // XGKICK addresses, in execution order
    std::vector<uint32_t> mem;      // VU1 data memory after the run
    std::vector<std::string> trace;
